using ghidra.util.exception;
using ghidra.util.map;

/**
 * Property manager that deals with properties that are of
 * int type.
 */
public class DefaultIntPropertyMap : DefaultPropertyMap<Integer>, IntPropertyMap {
	
    private IntValueMap ips;

 	/**
	 * Construct a new IntPropertyMap
	 * @param name name of property
	 */
	public DefaultIntPropertyMap(string name) : base(new IntValueMap(name))
    {
		ips = (IntValueMap)propertyMgr;
	}

	/* @Override */
	public void add(Address addr, int value) {
		ips.putInt(addrMap.getKey(addr), value);
	}
		
	/* @Override */
	public int getInt(Address addr)
    {
		return ips.getInt(addrMap.getKey(addr));
	}
	
	/* @Override */
	public Integer get(Address addr) {
		try {
			return getInt(addr);
		}
		catch (NoValueException e) {
			return null;
		}
	}

}
